import time

def moyenne(L):
    n = len(L)
    M = 0
    for k in range(n):
        M = M + L[k]
    return M/n

for n in [1000, 2000, 4000]:
    L = list(range(n))
    t = time.time()
    for _ in range(1000): moyenne(L)
    print(f'n={n}: {(time.time()-t)*1000:.1f}ms')

import time

def tri_selection(t):
    for i in range(len(t)):
        min_idx = i
        for j in range(i+1, len(t)):
            if t[j] < t[min_idx]: min_idx = j
        t[i], t[min_idx] = t[min_idx], t[i]

for n in [100, 200, 400]:
    import random
    L = [random.randint(0,1000) for _ in range(n)]
    t = time.time()
    tri_selection(L[:])
    print(f'n={n}: {(time.time()-t)*1000:.2f}ms')
